window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e8676ffa056cc30e"]={"versions": [{"id": "FIG-e8676ffa056cc30e", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses innerhalb der AUTOSAR E2E-Bibliothek (E2E Profile 1). Das Diagramm detailliert den Teilschritt <code>E2E_P01_handle_wrongSequence</code> als Unterfunktion des Prüfschritts <code>E2E_P01_process_counter</code> im Rahmen der Funktion <code>E2E_P01Check</code>. Es modelliert die Fehlerbehandlung bei Empfang einer Botschaft, deren Zählerdifferenz das zulässige Maximum überschritten hat (Sequenzfehler).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm operiert auf internen Zustands- und Konfigurationsstrukturen des E2E-Profils 1:</p>\n<ul class=\"fig-list\"><li><code>State</code>: Zeiger auf den Zustandsspeicher (<code>E2E_P01CheckStateType</code>) mit den Attributen <code>NoNewOrRepeatedDataCounter</code>, <code>SyncCounter</code>, <code>MaxDeltaCounter</code> und <code>LastValidCounter</code>.\n</li><li><code>Config</code>: Zeiger auf die konstante Konfigurationsstruktur (<code>E2E_P01ConfigType</code>) mit den Konfigurationsparametern <code>SyncCounterInit</code> und <code>MaxDeltaCounterInit</code>.\n</li><li><code>ReceivedCounter</code>: Lokale Eingangsvariable, die den aus der empfangenen Botschaft extrahierten Sequenzzähler darstellt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf beginnt am Startknoten und verläuft wie folgt:</p>\n<ol class=\"fig-list\"><li>Zuweisung: <code>State-&gt;NoNewOrRepeatedDataCounter = 0</code> setzt den Zähler für fehlende oder wiederholte Botschaften zurück.\n</li><li>Zuweisung: <code>State-&gt;SyncCounter = Config-&gt;SyncCounterInit</code> initialisiert den Synchronisationszähler mit dem vorkonfigurierten Startwert.\n</li><li>Verzweigungsknoten prüft die Bedingung <code>State-&gt;SyncCounter &gt; 0</code>:\n<ul class=\"fig-list\"><li><code>[TRUE]</code>: <code>State-&gt;MaxDeltaCounter</code> wird mit <code>Config-&gt;MaxDeltaCounterInit</code> neu initialisiert, und <code>State-&gt;LastValidCounter</code> wird auf <code>ReceivedCounter</code> aktualisiert.\n</li><li><code>[FALSE]</code>: Der Zweig umgeht die Neuinitialisierung von <code>MaxDeltaCounter</code> und <code>LastValidCounter</code> direkt zum Zusammenführungsknoten.\n</li></ul>\n</li><li>Nach Zusammenführung der beiden Zweige endet die Aktivität am Endknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der Fehlerbehandlung für Profil 1 (<code>E2E_P01_handle_wrongSequence</code>). Implementierende Softwarekomponenten bzw. der E2E-Treiber müssen sicherstellen, dass bei Detektion einer ungültigen Sequenz <code>NoNewOrRepeatedDataCounter</code> genullt und <code>SyncCounter</code> zurückgesetzt wird. Die Aktualisierung von <code>LastValidCounter</code> und die Re-Initialisierung von <code>MaxDeltaCounter</code> erfolgen strikt konditional in Abhängigkeit des initialisierten Synchronisationszählers (<code>SyncCounter &gt; 0</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1fa84c0962b534a3", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses innerhalb der AUTOSAR E2E-Bibliothek (E2E Profile 1). Das Diagramm detailliert den Teilschritt <code>E2E_P01_handle_wrongSequence</code> als Unterfunktion des Prüfschritts <code>E2E_P01_process_counter</code> im Rahmen der Funktion <code>E2E_P01Check</code>. Es modelliert die Fehlerbehandlung bei Empfang einer Botschaft, deren Zählerdifferenz das zulässige Maximum überschritten hat (Sequenzfehler).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm operiert auf internen Zustands- und Konfigurationsstrukturen des E2E-Profils 1:</p>\n<ul class=\"fig-list\"><li><code>State</code>: Zeiger auf den Zustandsspeicher (<code>E2E_P01CheckStateType</code>) mit den Attributen <code>NoNewOrRepeatedDataCounter</code>, <code>SyncCounter</code>, <code>MaxDeltaCounter</code> und <code>LastValidCounter</code>.\n</li><li><code>Config</code>: Zeiger auf die konstante Konfigurationsstruktur (<code>E2E_P01ConfigType</code>) mit den Konfigurationsparametern <code>SyncCounterInit</code> und <code>MaxDeltaCounterInit</code>.\n</li><li><code>ReceivedCounter</code>: Lokale Eingangsvariable, die den aus der empfangenen Botschaft extrahierten Sequenzzähler darstellt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf beginnt am Startknoten und verläuft wie folgt:</p>\n<ol class=\"fig-list\"><li>Zuweisung: <code>State-&gt;NoNewOrRepeatedDataCounter = 0</code> setzt den Zähler für fehlende oder wiederholte Botschaften zurück.\n</li><li>Zuweisung: <code>State-&gt;SyncCounter = Config-&gt;SyncCounterInit</code> initialisiert den Synchronisationszähler mit dem vorkonfigurierten Startwert.\n</li><li>Verzweigungsknoten prüft die Bedingung <code>State-&gt;SyncCounter &gt; 0</code>:\n<ul class=\"fig-list\"><li><code>[TRUE]</code>: <code>State-&gt;MaxDeltaCounter</code> wird mit <code>Config-&gt;MaxDeltaCounterInit</code> neu initialisiert, und <code>State-&gt;LastValidCounter</code> wird auf <code>ReceivedCounter</code> aktualisiert.\n</li><li><code>[FALSE]</code>: Der Zweig umgeht die Neuinitialisierung von <code>MaxDeltaCounter</code> und <code>LastValidCounter</code> direkt zum Zusammenführungsknoten.\n</li></ul>\n</li><li>Nach Zusammenführung der beiden Zweige endet die Aktivität am Endknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der Fehlerbehandlung für Profil 1 (<code>E2E_P01_handle_wrongSequence</code>). Implementierende Softwarekomponenten bzw. der E2E-Treiber müssen sicherstellen, dass bei Detektion einer ungültigen Sequenz <code>NoNewOrRepeatedDataCounter</code> genullt und <code>SyncCounter</code> zurückgesetzt wird. Die Aktualisierung von <code>LastValidCounter</code> und die Re-Initialisierung von <code>MaxDeltaCounter</code> erfolgen strikt konditional in Abhängigkeit des initialisierten Synchronisationszählers (<code>SyncCounter &gt; 0</code>).</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-e8676ffa056cc30e", "to": "FIG-1fa84c0962b534a3", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
